ALTER TABLE facilities ADD COLUMN frai_score NUMERIC(3,2);
UPDATE facilities SET frai_score = CASE 
    WHEN json_extract(support_and_resources, '$.community_resources') = 'Comprehensive' THEN 3.0 
    WHEN json_extract(support_and_resources, '$.community_resources') = 'Adequate' THEN 2.0 
    WHEN json_extract(support_and_resources, '$.community_resources') = 'Limited' THEN 1.0 
END;

